/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202609151440027_CopilotPromptSafetyFields
   =====================================================================================================
   For operators / DBAs who upgrade the Analytics database schema BY HAND instead of running the
   installer (which applies EF migrations automatically). It performs the same schema changes as the
   migration and then stamps __MigrationHistory so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion)
   and the web app Health page recognise it as applied.

   RUN ORDER
     The manual scripts form a strict prerequisite chain - run them in migration-id order. This one's
     predecessor is 202609131940001_CopilotReclaimEligibilityInputs. If that migration is not
     already stamped in __MigrationHistory this script applies its columns but deliberately does NOT
     stamp, and tells you so.

   WHAT IT DOES
     Persists the two Copilot prompt-safety flags the importer parsed but never stored (issue #570).
     Both are documented on https://learn.microsoft.com/en-us/purview/audit-copilot but absent from the
     older OData Management API schema, which is why they were missed.

     New columns
       * copilot_event_messages.jailbreak_detected       - bit NULL. Was a jailbreak attempt detected in
                                                           this prompt message.
       * copilot_event_accessed_resources.xpia_detected  - bit NULL. Was a Cross-Prompt Injection Attack
                                                           detected from this accessed resource.

     NO BACKFILL is performed: existing rows keep NULL and are populated only for newly imported
     interactions. Note this is a CHOICE, not a limitation - unlike the 7-day Management Activity API
     window that made 202608190622001 impossible to backfill, these values are already on disk in
     audit_events.event_data (the importer stores the raw payload) and could be recovered with
     JSON_VALUE. That is deliberately not done here: it would be an unbounded UPDATE over the two
     largest Copilot tables, which does not belong in an upgrade script.

   RUNTIME
     Instant, at any table size, on every SQL Server edition.

     Both statements are ALTER TABLE ... ADD of a NULLable column with NO DEFAULT, which SQL Server
     applies as a metadata-only change - it does not rewrite the table and does not scan it. There is no
     index build and no foreign key, so there is nothing here that takes a schema-modification lock for
     any meaningful duration.

     This is the significant difference from 202608190622001_CopilotDroppedAuditFields, whose two
     FOREIGN KEYS did force a full Sch-M-locked validation scan and therefore needed a maintenance
     window on large databases. This script does not. It is safe to run with the importer running.

   SAFETY
     * Idempotent: every step is guarded and re-running is a no-op.
     * The stamp is guarded and is reached on the "already applied" path as well, so running this
       against an already-up-to-date database still reconciles __MigrationHistory rather than leaving
       the migration pending.
     * The stamp refuses only if the COLUMNS are missing - i.e. the schema work did not complete. It
       never inspects row data. (A data-state guard has broken a customer upgrade before: concurrency
       always beats it, and EF's own installer path does not apply one.)
   ===================================================================================================== */

SET NOCOUNT ON;
GO

/* =====================================================================================================
   1. copilot_event_accessed_resources.xpia_detected
   ===================================================================================================== */
IF OBJECT_ID(N'dbo.copilot_event_accessed_resources', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_event_accessed_resources', N'xpia_detected') IS NULL
BEGIN
    ALTER TABLE [dbo].[copilot_event_accessed_resources] ADD [xpia_detected] [bit] NULL;
    RAISERROR('CopilotPromptSafetyFields: added copilot_event_accessed_resources.xpia_detected.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('CopilotPromptSafetyFields: copilot_event_accessed_resources.xpia_detected already present (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO

/* =====================================================================================================
   2. copilot_event_messages.jailbreak_detected
   ===================================================================================================== */
IF OBJECT_ID(N'dbo.copilot_event_messages', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_event_messages', N'jailbreak_detected') IS NULL
BEGIN
    ALTER TABLE [dbo].[copilot_event_messages] ADD [jailbreak_detected] [bit] NULL;
    RAISERROR('CopilotPromptSafetyFields: added copilot_event_messages.jailbreak_detected.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('CopilotPromptSafetyFields: copilot_event_messages.jailbreak_detected already present (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO

/* =====================================================================================================
   3. Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web app
      Health page treat it as applied.

      This migration DOES change the EF entity model, so the predecessor's Model blob cannot be reused:
      EF reads the LAST history row's Model as the source for automatic migrations, and a stale blob
      would make it try to re-add these columns. The model snapshot below is the gzipped EDMX from
      202609151440027_CopilotPromptSafetyFields.resx, emitted in chunks so no single line is
      unreasonably long. Guarded, so re-running is safe.
   ===================================================================================================== */
IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609151440027_CopilotPromptSafetyFields')
BEGIN
    /* ---------------------------------------------------------------------------------------------
       Refuse to stamp unless the schema work above actually completed.

       This script is split into GO batches, and by default sqlcmd/SSMS CONTINUE to the next batch after
       a statement fails - a severity-16 error aborts its own batch, not the script. Without this check
       an interrupted or partially failed run would fall through to the stamp and record the migration
       as applied when it is not, which is worse than the original error: EF would then believe the
       schema is at this version and skip the migration forever.

       This checks SCHEMA ONLY - do the columns exist. It deliberately does not look at row data.
       --------------------------------------------------------------------------------------------- */
    DECLARE @missing nvarchar(max) = N'';

    IF COL_LENGTH(N'dbo.copilot_event_accessed_resources', N'xpia_detected') IS NULL
        SET @missing += N'copilot_event_accessed_resources.xpia_detected; ';
    IF COL_LENGTH(N'dbo.copilot_event_messages', N'jailbreak_detected') IS NULL
        SET @missing += N'copilot_event_messages.jailbreak_detected; ';

    IF @missing <> N''
    BEGIN
        DECLARE @incomplete nvarchar(max) =
            N'CopilotPromptSafetyFields: NOT stamped - the schema changes did not complete. Missing: '
            + @missing
            + N'Re-run this script (it is guarded and safe to repeat) and check the earlier output for the '
            + N'failure. The migration is deliberately left unstamped so the upgrade can be retried.';
        RAISERROR(@incomplete, 16, 1) WITH NOWAIT;
    END
    ELSE
    IF EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609131940001_CopilotReclaimEligibilityInputs')
    BEGIN
        DECLARE @model varbinary(max);
 SET @model = 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 
 SET @model = @model + 

        INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
        SELECT N'202609151440027_CopilotPromptSafetyFields', ContextKey, @model, ProductVersion
        FROM dbo.__MigrationHistory
        WHERE MigrationId = N'202609131940001_CopilotReclaimEligibilityInputs';
        RAISERROR('CopilotPromptSafetyFields: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
    END
    ELSE
        RAISERROR('CopilotPromptSafetyFields: the schema changes were applied, but prerequisite migration 202609131940001_CopilotReclaimEligibilityInputs is missing from __MigrationHistory, so it was NOT stamped. Upgrade to the previous release first, or run the installer to reconcile.', 16, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('CopilotPromptSafetyFields: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;
GO